pub(crate) async fn describe_qualified_written<H: DescribeHost>(root: &std::path::Path, contracts: &str, host: &H) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut pending: Vec<fs::Path> = nikaia_std::block::List::from_array_in([nikaia_std::fs::path::clone(&(root))], nikaia_std::block::Place::Block);
    loop {
        let directory = match pending.pop() { Some(__nikaia_value) => __nikaia_value, None => break };
        let names = match fs::read_dir(&directory, &fs::Root::Anywhere) {
            Ok(value) => value,
            Err(_error) => { continue; },
        };
        for name in names.iter() {
            let path = nikaia_std::fs::path::join(&(directory), name);
            let meta = match fs::metadata(&path, &fs::Root::Anywhere) {
                Ok(value) => value,
                Err(_error) => { continue; },
            };
            if meta.is_dir() {
                let word = nikaia_std::fs::path::text_of(&(name));
                if word != "target" && word != contracts { pending.push(path); }
                continue;
            }
            if nikaia_std::index::or(match nikaia_std::fs::path::extension(&(path)).as_ref() {
                Some(__nikaia_it) => Some(nikaia_std::fs::path::text_of(&(__nikaia_it))),
                None => None,
            }, || "".into()) != "nika" { continue; }
            let text = match fs::read_to_string(&path, &fs::Root::Anywhere).await {
                Ok(value) => value,
                Err(_error) => { continue; },
            };
            let written = match host.qualified_names(&text) { Some(__nikaia_value) => __nikaia_value, None => continue };
            for qualified in written.iter() { out.insert(nikaia_std::block::Text::from(qualified.to_string())); }
        }
    }
    out
}

pub fn describe_without_dots(path: &std::path::Path) -> fs::Path {
    let mut out: fs::Path = std::path::PathBuf::from("");
    for part in nikaia_std::fs::path::parts(&(path)) {
        if nikaia_std::fs::path::same(&(part), &(".")) { continue; }
        if nikaia_std::fs::path::same(&(part), &("..")) {
            out = match nikaia_std::fs::path::parent(&(out)) { Some(__nikaia_value) => __nikaia_value, None => continue };
            continue;
        }
        out = nikaia_std::fs::path::join(&(out), &part);
    }
    out
}

